    parts = lines[0].split()
    n, k = int(parts[0]), int(parts[1])
    v = list(map(int, lines[1].split()))
    c = list(map(int, lines[2].split()))

    # For each position i, f[i] = max over all r >= i of min(100 * max(v[i..r]), min(c[i..r]))
    # Use sparse table for O(1) range max/min queries after O(n log n) preprocessing

    def build_log_table(size):
        LOG = [0] * (size + 1)
        for i in range(2, size + 1):
            LOG[i] = LOG[i // 2] + 1
        return LOG

    log_table = build_log_table(n + 1)

    def build_sparse_table(arr):
        k_log = log_table[len(arr)]
        st = [[0] * len(arr) for _ in range(k_log + 1)]
        for i in range(len(arr)):
            st[0][i] = arr[i]
        for j in range(1, k_log + 1):
            for i in range(len(arr) - (1 << j) + 1):
                st[j][i] = max(st[j-1][i], st[j-1][i + (1 << (j-1))])
        return st

    st_max = build_sparse_table(v)
    st_min = build_sparse_table(c)

    def query_max(l, r):  # inclusive [l, r], 0-indexed
        length = r - l + 1
        k = log_table[length]
        return max(st_max[k][l], st_max[k][r - (1 << k) + 1])

    def query_min(l, r):  # inclusive [l, r], 0-indexed
        length = r - l + 1
        k = log_table[length]
        return min(st_min[k][l], st_min[k][r - (1 << k) + 1])

    INF = float('inf')
    f = [0] * n

    # For each starting position, find best ending position
    for i in range(n):
        best = 0
        for j in range(i, n):
            max_visitors = query_max(i, j)
            min_revenue = query_min(i, j)
            potential = min(max_visitors * 100, min_revenue)
            if potential > best:
                best = potential
        f[i] = best

    f.sort()

    # Calculate expected minimum of k random selections
    def nCk_pairwise(n, k):
        if k < 0 or k > n:
            return 0
        result = 1
        for i in range(k):
            result = result * (n - i) // (i + 1)
        return result

    total = nCk_pairwise(n, k)
    expected = 0.0

    # P(min == f[j]) = C(n-1-j, k-1) / C(n, k) for j in [0, k-1]
    # Using 0-indexed: P(min is j-th smallest, j starting from 0) = C(n-1-j, k-1) / C(n, k)
    for j in range(min(n, k)):
        remaining = n - 1 - j
        if remaining >= k - 1:
            num = nCk_pairwise(remaining, k - 1)
            expected += f[j] * num / total

    return f"{expected:.15f}\n"
