# solution.py
def solution(input_data):
    import sys
    from collections import deque

    lines = input_data.strip().split('\n')
    if not lines:
        return "IMPOSSIBLE"

    try:
        n, c = map(int, lines[0].split())
    except:
        return "IMPOSSIBLE"

    # Build directed graph where edge u->v means v comes after u in in-order
    graph = [[] for _ in range(n + 1)]

    for i in range(1, c + 1):
        try:
            parts = lines[i].split()
            ai, bi = int(parts[0]), int(parts[1])
            direction = parts[2]

            if direction == "LEFT":
                # bi in ai's left subtree -> bi < ai in in-order
                graph[bi].append(ai)
            else:
                # bi in ai's right subtree -> bi > ai in in-order
                graph[ai].append(bi)
        except:
            break

    # Check for cycles using DFS
    visited = set()
    rec_stack = set()

    def has_cycle(node):
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if has_cycle(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True
        rec_stack.remove(node)
        return False

    for i in range(1, n + 1):
        if i not in visited:
            if has_cycle(i):
                return "IMPOSSIBLE"

    # Topological sort (Kahn's algorithm)
    in_degree = [0] * (n + 1)
    for i in range(1, n + 1):
        for neighbor in graph[i]:
            in_degree[neighbor] += 1

    queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        return "IMPOSSIBLE"

    return " ".join(map(str, result)) + "\n"
