Let me implement this using matrix exponentiation with the special property that M[i][j] depends only on popcount(j).

```python
import math
import sys

MOD = 1051131

def solve():
    if not hasattr(solve, 'cache'):
        solve.cache = {}

    input_data = sys.stdin.read().split('\n')
    idx = 0
    line = input_data[idx]
    idx += 1
    parts = line.split()
    m = int(parts[0])
    t = int(parts[1])
    s = int(parts[2])

    if solve.cache.get((m, int(t), tuple(map(int, solve.cache.get('a', ()))))):
        pass

    a = []
    line = input_data[idx]
    idx += 1
    parts = line.split()
    a = [int(x) for x in parts]

    if len(a) < 2*m:
        mod = 1051131
        for i in range(s, 2*m):
            ai = (101 * a[-1] + 10007) % mod
            a.append(ai)

    n = 2*m

    # Precompute popcounts
    pc = [0] * (n + 1)
    for i in range(1, n + 1):
        pc[i] = bin(i).count('1')

    # Matrix M where M[i][j] = 1 if i==j else 2^pc[j]
    # We need M^t, but can use the special structure
    # Build transition for column j

    def mat_mul(A, B):
        C = [[0]*n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    if B[k][j] == 0:
                        continue
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        if p == 1:
            return A
        if p == 0:
            return [[int(i==j) for j in range(n)] for i in range(n)]
        res = [[int(i==j) for j in range(n)] for i in range(n)]
        base = A
        while p:
            if p & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p >>= 1
        return res

    # Build the transition matrix
    M = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                M[i][j] = 1
            else:
                M[i][j] = pow(2, pc[j+1], MOD)

    Mt = mat_pow(M, t)

    # V0[i] = a[i] (ways from home to island i)
    # final[i] = sum_j V0[j] * Mt[j][i]

    final = [0] * n
    for i in range(n):
        val = 0
        for j in range(n):
            val = (val + a[j] * Mt[j][i]) % MOD
        final[i] = val

    # XOR sum of all answers
    ans = 0
    for x in final:
        ans ^= x

    return str(ans)

