```python
import sys
from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        return True


def solution(input_str):
    """
    Find minimum cost spanning tree with exactly k capital roads.
    Capital roads are those connected to city 1.
    """

    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    # Parse edges, storing original index (1-based)
    edges = []
    idx = 1
    for i in range(1, m + 1):
        parts = lines[idx].split()
        idx += 1
        a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, w, i))

    # Special case: n=1
    if n == 1:
        return "0\n\n"

    # Separate capital edges (connected to node 1)
    capital_edges = [(u, v, w, i) for u, v, w, i in edges if u == 1 or v == 1]
    non_capital_edges = [(u, v, w, i) for u, v, w, i in edges if u != 1 and v != 1]

    # Sort by weight
    capital_edges.sort(key=lambda x: x[2])
    non_capital_edges.sort(key=lambda x: x[2])

    # Check feasibility: we need at least k capital edges and enough edges total
    if len(capital_edges) < k or len(edges) < n:
        return "-1\n"

    best_solution = None

    # Try selecting exactly 'num_capital' capital edges
    # and fill remaining with non-capital edges optimally
    for num_capital in range(1, min(len(capital_edges) + 1, k + 1, n - 1 + 1)):
        uf = UnionFind(n)
        selected_indices = []
        capital_used = 0

        # First, select 'num_capital' capital edges greedily
        for u, v, w, i in capital_edges:
            if capital_used < num_capital and uf.union(u, v):
                selected_indices.append(i)
                capital_used += 1

        # If we couldn't get num_capital edges, this choice is invalid
        if capital_used < num_capital:
            continue

        # Then add non-capital edges
        for u, v, w, i in non_capital_edges:
            if uf.union(u, v):
                selected_indices.append(i)

        # Check if all nodes are connected
        root = uf.find(1)
        all_connected = all(uf.find(i) == root for i in range(1, n + 1))

        if all_connected and len(selected_indices) == n - 1:
            # Convert to sorted output
            selected_indices.sort()
            result_str = f"{len(selected_indices)}\n{' '.join(map(str, selected_indices))} \n"
            if best_solution is None or result_str == best_solution:
                best_solution = result_str

    # If no valid solution found, return -1
    if best_solution is None:
        return "-1\n"

    return best_solution


