            idx2 = r * 5 + min(c + 1, lengths[r] - 1) + r // 2
            lines_list.append((min(idx1, idx2), max(idx1, idx2)))

    # Compute Grundy value and return winner
    @functools.lru_cache(None)
    def grundy(m):
        if m == 0:
            return 0
        reachable = set()
        for i in range(26):
            for j in range(i + 1, 26):
                if ((m >> i) & 1) and ((m >> j) & 1):
                    reachable.add(grundy(m ^ ((1 << i) | (1 << j))))
        mex = 0
        while mex in reachable:
            mex += 1
        return mex

    # Return Karlsson if grundy is non-zero, else Lillebror
    return "Karlsson" if grundy(mask) > 0 else "Lillebror"
