Looking at this problem, I need to solve it properly since it's a competitive programming problem that tests graph theory/geometry knowledge. The approach is to:

1. Identify when two roads would intersect if both placed inside the ring (when their endpoints alternate around the ring)
2. Build a conflict graph where edges represent pairs of roads that intersect if both inside
3. 2-color the connected components of this conflict graph (if bipartite)
4. If not bipartite, output "Impossible"

Let me implement the proper solution:

```python
# Your solution code
def solution(problem):
    lines = problem.strip().split('\n')
    n, m = map(int, lines[0].split())

    roads = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        roads.append((a, b))

    # Check if two chords intersect inside the ring
    # Two chords (a1,b1) and (a2,b2) intersect if their endpoints alternate
    def between(a, start, end, n):
        """Check if a is strictly clockwise between start and end"""
        if start <= end:
            return start < a < end
        else:  # start > end (wraps around)
            return start > a or end >= a

    def would_intersect(r1, r2, n):
        a1, b1 = r1
        a2, b2 = r2

        # Check if exactly one endpoint of r2 is strictly between endpoints of r1
        a2_in = between(a2, a1, b1, n)
        b2_in = between(b2, a1, b1, n)
        return a2_in != b2_in

    # Build conflict graph (roads that would intersect if both inside)
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if would_intersect(roads[i], roads[j], n):
                adj[i].append(j)
                adj[j].append(i)

    # 2-color the conflict graph (bipartite check)
    color = [-1] * m
    result = ['i'] * m  # Default assignment
    possible = True

    def dfs(u, c):
        nonlocal possible
        color[u] = c
        if c == 1:
            result[u] = 'i'
        else:
            result[u] = 'o'

        for v in adj[u]:
            if color[v] == -1:
                dfs(v, 1 - c)
            elif color[v] == c:
                possible = False
                return

    for i in range(m):
        if color[i] == -1:
            dfs(i, 1)
            if not possible:
                break

    if possible:
        return ''.join(result)
    else:
        return 'Impossible'
```

