def solution(input_str):
    """
    Solution to the grocery coupon problem.

    The problem describes a scenario where:
    - Items have base prices and discounts available via coupons
    - Coupons have hierarchical dependencies (using coupon i requires using coupon parent[i])
    - Goal: maximize items within budget

    This creates a tree structure where parent relationships define coupon dependencies.
    """
    lines = input_str.strip().split('\n')
    n, b = map(int, lines[0].split())

    c = []
    d = []
    p = []  # parent of each item

    for i in range(n):
        parts = list(map(int, lines[1+i].split()))
        c.append(parts[0])
        d.append(parts[1])
        if len(parts) > 2:
            p.append(parts[2] - 1)  # 0-indexed
        else:
            p.append(-1)

    # Build tree (adjacency list for children)
    children = [[] for _ in range(n)]
    for i in range(1, n):
        if p[i] != -1:
            children[p[i]].append(i)

    from functools import lru_cache

    INF = float('inf')

    @lru_cache(maxsize=None)
    def solve(u, parent_uses_coupon):
        """
        Returns a tuple of (count, min_cost) pairs for subtree rooted at u.
        parent_uses_coupon: whether parent's coupon was used (required for using u's coupon)
        """
        # Start with base options for node u
        result = {0: 0}

        # Option 1: Don't buy node u
        result[0] = 0

        # Option 2: Buy node u at full price
        result[1] = c[u]

        # Option 3: Buy node u with coupon (only if parent's coupon is available)
        if parent_uses_coupon:
            result[1] = min(result[1], c[u] - d[u])

        # Merge results from all children
        for v in children[u]:
            child_res = solve(v, parent_uses_coupon)
            child_res_list = list(child_res.items())

            for cnt_child, cost_child in child_res_list:
                for cnt_base, cost_base in list(result.items()):
                    new_cnt = cnt_base + cnt_child
                    new_cost = cost_base + cost_child
                    if new_cnt > len(result) or result.get(new_cnt, INF) > new_cost:
                        result[new_cnt] = new_cost

        # Prune: remove dominated states
        # A state (count1, cost1) dominates (count2, cost2) if count1 >= count2 and cost1 <= cost2
        sorted_items = sorted(result.items(), key=lambda x: (x[0], x[1]))

        pruned = {}
        min_cost_so_far = INF
        for cnt, cost in sorted_items:
            # If this state has more items with same or lower cost, previous states are dominated
            if cost <= min_cost_so_far:
                min_cost_so_far = cost
                pruned[cnt] = cost

        return tuple(sorted(pruned.items()))

    # Compute solution for root (item 0 has no parent, so parent_uses_coupon=True)
    res = solve(0, True)

    # Find maximum items within budget
    ans = 0
    for cnt, cost in res:
        if cost <= b:
            ans = max(ans, cnt)

    return str(ans)

